mapper.select:
SELECT ib.*, bm.bloodline_name
FROM individual_bloodline ib
INNER JOIN bloodline_master bm
    ON bm.species_id = ib.species_id
    AND bm.morph_id = ib.morph_id
    AND bm.bloodline_id = ib.bloodline_id
WHERE ib.species_id = #{speciesId}
  AND ib.individual_id = #{individualId}
  AND ib.morph_id = #{morphId}

mapper.insert:
INSERT INTO individual_bloodline (
    species_id, individual_id, morph_id, bloodline_id,
    create_user, create_at, update_user, update_at
) VALUES (
    #{speciesId}, #{individualId}, #{morphId}, #{bloodlineId},
    #{createUser}, #{createAt}, #{updateUser}, #{updateAt}
)

mapper.delete:
DELETE FROM individual_bloodline
WHERE species_id = #{speciesId}
  AND individual_id = #{individualId}
